export type CameraModel = 'iPhone 13 Pro' | 'iPhone 14 Pro' | 'iPhone 15 Pro Max' | 'iPhone 16 Pro Max';
export type CameraMode = 'Standard' | 'ProRAW' | 'Smart HDR' | 'Macro' | 'Night Mode' | 'Cinematic';
export type FocalLength = '13mm' | '24mm' | '35mm' | '48mm' | '77mm' | '120mm';
export type LensType = 'Ultra Wide' | 'Main' | 'Telephoto';
export type RealismLevel = 'Natural' | 'Enhanced' | 'Professional Master';

export interface CameraSettings {
  model: CameraModel;
  mode: CameraMode;
  focalLength: FocalLength;
  lensType: LensType;
  realism: RealismLevel;
}

export interface PromptResult {
  positive: string;
  negative: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { CameraSettings, PromptResult } from "../types";

const SYSTEM_INSTRUCTION = `You are a world-class photography expert specializing in ultra-realistic iPhone cinematography and photography. 
Your goal is to analyze an uploaded image and generate two specific prompts: a positive prompt and a negative prompt.

CRITICAL RULES:
1. DO NOT mention facial features, identity, ethnicity, skin tone, or specific physical appearance details of people. Focus only on their clothing, pose, accessories, and position in the frame.
2. The style must be strictly 'iPhone Realism'. Use technical terms related to iPhone photography (Smart HDR, Deep Fusion, ProRAW).
3. Describe EVERYTHING else: environment, lighting (natural, soft, direct), shadows, weather, composition (rule of thirds, leading lines), mood, textures, and photographic artifacts.
4. Ensure the tone is technical, professional, and evocative of high-end commercial photography.
5. The output MUST be a JSON object with keys 'positive' and 'negative'.

POSITIVE PROMPT STRUCTURE:
- [Camera Specs provided by user]
- [Environment details]
- [Lighting and Shadow details]
- [Composition and Angle]
- [Subject pose and attire (excluding identity)]
- [Specific iPhone characteristic: grain, color science, dynamic range]

NEGATIVE PROMPT STRUCTURE:
- Standard AI artifacts: plastic skin, fake lighting, oversaturation, distortion, watermark, low resolution, extra fingers, cartoonish look, unreal highlights.`;

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const prompt = `Analyze this image and generate a highly detailed prompt for an AI image generator to recreate this exact scene. 
  Follow the provided camera settings:
  - Model: ${settings.model}
  - Mode: ${settings.mode}
  - Focal Length: ${settings.focalLength}
  - Lens: ${settings.lensType}
  - Realism Style: ${settings.realism}

  Format the output as JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            { text: prompt },
            {
              inlineData: {
                mimeType: 'image/jpeg',
                data: imageBuffer.split(',')[1],
              },
            },
          ],
        },
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            positive: { type: Type.STRING },
            negative: { type: Type.STRING },
          },
          required: ["positive", "negative"],
        },
      },
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from AI");

    return JSON.parse(resultText) as PromptResult;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

