  const [image, setImage] = useState<string | null>(null);
  const [result, setResult] = useState<PromptResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setResult(null);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!image) return;

    setIsLoading(true);
    setError(null);
    try {
      const data = await generatePrompts(image, settings);
      setResult(data);
    } catch (err) {
      setError("Failed to generate prompt. Please check your API key and try again.");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <nav className="sticky top-0 z-50 apple-blur border-b border-gray-100 px-6 py-4">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-black rounded-lg flex items-center justify-center">
              <div className="w-4 h-4 rounded-full border-2 border-white"></div>
            </div>
            <h1 className="text-xl font-display font-bold tracking-tight">LuxLens</h1>
          </div>
          <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">
            AI-Powered Image Synthesis
          </div>
        </div>
      </nav>

      <main className="max-w-6xl mx-auto px-6 pt-12">
        <header className="mb-12 text-center max-w-2xl mx-auto">
          <h2 className="text-4xl font-display font-bold mb-4 gradient-text">
            Reimagine Your Scenes
          </h2>
          <p className="text-gray-500 text-lg">
            Upload any photo and let our AI reverse-engineer its composition into a master-grade iPhone photography prompt.
          </p>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
          {/* Controls Column */}
          <div className="lg:col-span-5 space-y-8">
