                onChange={handleImageUpload}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
              />
              <div className={`
                aspect-[4/3] rounded-3xl border-2 border-dashed flex flex-col items-center justify-center transition-all duration-300
                ${image ? 'border-transparent bg-gray-50' : 'border-gray-200 bg-white hover:border-gray-300'}
              `}>
                {image ? (
                  <img src={image} className="w-full h-full object-cover rounded-3xl shadow-sm" alt="Preview" />
                ) : (
                  <div className="text-center p-8">
                    <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                      <svg className="w-6 h-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                      </svg>
                    </div>
                    <span className="text-sm font-medium text-gray-500">Tap to upload reference image</span>
                    <p className="text-[10px] text-gray-400 mt-2 uppercase tracking-widest">JPG, PNG, WEBP</p>
                  </div>
                )}
              </div>
              {image && (
                <button 
                  onClick={() => setImage(null)}
                  className="absolute -top-3 -right-3 bg-white w-8 h-8 rounded-full shadow-lg border border-gray-100 flex items-center justify-center z-20 hover:bg-red-50 text-red-500 transition-colors"
