              className={`
                w-full py-4 rounded-2xl font-semibold text-white transition-all shadow-xl shadow-blue-500/20 active:scale-95
                ${!image || isLoading ? 'bg-gray-300 cursor-not-allowed shadow-none' : 'bg-blue-600 hover:bg-blue-700'}
              `}
            >
              {isLoading ? (
                <div className="flex items-center justify-center gap-2">
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  <span>Analyzing Exposure...</span>
