import { GoogleGenAI } from "@google/genai";
import { CameraSettings, PromptResult } from "../types";

const SYSTEM_INSTRUCTION = `You are a world-class photography expert specializing in ultra-realistic iPhone cinematography and photography. 
Your goal is to analyze an uploaded image and generate a SINGLE, consolidated prompt that includes both description and negative constraints.

CRITICAL RULES:
1. DO NOT mention facial features, identity, ethnicity, skin tone, or specific physical appearance details of people. Focus only on their clothing, pose, accessories, and position in the frame.
2. ABSOLUTELY NO TATTOOS, SCARS, BIRTHMARKS, OR BODY MARKINGS. Describe skin as clear, natural, and unblemished. 
3. The style must be strictly 'iPhone Realism'. Use technical terms related to iPhone photography (Smart HDR, Deep Fusion, ProRAW).
4. Describe EVERYTHING else: environment, lighting (natural, soft, direct), shadows, weather, composition (rule of thirds, leading lines), mood, textures, and photographic artifacts.
5. Combine the positive description and negative constraints into one text block.
6. Format: [Detailed Positive Description] --no [Negative Constraints]

POSITIVE DESCRIPTION:
- [Camera Specs provided by user]
- [Environment details]
- [Lighting and Shadow details]
- [Composition and Angle]
- [Subject pose and attire (excluding identity/tattoos)]
- [Specific iPhone characteristic: grain, color science, dynamic range]

NEGATIVE CONSTRAINTS (to be added after --no):
- tattoos, body markings, text, watermark, facial features, makeup, plastic skin, fake lighting, oversaturation, distortion, low resolution, extra fingers, cartoonish look, unreal highlights, bad anatomy.`;

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const prompt = `Analyze this image and generate a master prompt.
  Camera Config:
  - Model: ${settings.model}
  - Mode: ${settings.mode}
  - Focal Length: ${settings.focalLength}
  - Lens: ${settings.lensType}
  - Realism Style: ${settings.realism}

  Remember: No tattoos, no specific identity, no faces. Return raw text only.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            { text: prompt },
            {
              inlineData: {
                mimeType: 'image/jpeg',
                data: imageBuffer.split(',')[1],
              },
            },
          ],
        },
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from AI");

    return resultText;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

