import { GoogleGenAI } from "@google/genai";
import { CameraSettings, PromptResult } from "../types";

const SYSTEM_INSTRUCTION = `You are a world-class Director of Photography (DoP) and Colorist. 
Your goal is to reverse-engineer an image into a prompt that produces results indistinguishable from real life.

KEY OBJECTIVE: ELIMINATE THE "AI LOOK".
AI images often look flat, too perfect, smooth, and plastic. You must force the generation of "optical flaws" and "atmospheric depth" to create ALIVENESS.

CRITICAL RULES:
1. **NO FACES/IDENTITY:** Do not describe facial features. Focus on posture, vibe, and silhouette.
2. **NO TATTOOS/MARKINGS:** Explicitly forbid tattoos and clear skin in the negative prompt.
3. **DEPTH & ATMOSPHERE:** The background must NOT be flat. Describe the air (hazy, dusty, humid, clear). Describe depth of field (bokeh, focus falloff).
4. **IMPERFECTIONS:** Mention "sensor noise," "film grain," "slight chromatic aberration," "motion blur," or "imperfect framing" to sell the realism.
5. **LIGHTING:** Avoid "studio lighting" unless obvious. Use "diegetic lighting," "bounce light," "subsurface scattering" (light passing through skin/ears), and "harsh shadows" if appropriate.
6. **FORMAT:** [Detailed Positive Description] --no [Negative Constraints]

POSITIVE DESCRIPTION STRUCTURE:
- **Camera Gear:** (e.g., "Shot on iPhone 15 Pro Max, 24mm lens, ISO 400, f/1.8")
- **The Shot:** "Raw photography, candid snapshot, unedited footage."
- **Subject:** Pose, clothing texture (thread count, fabric weight), interaction with environment.
- **Environment & Background:** DO NOT just say "a street." Say "a busy street with motion-blurred cars, dirty pavement, uneven concrete, trash on the sidewalk, atmospheric city haze." MAKE IT MESSY AND ALIVE.
- **Lighting:** Direction, temperature (warm/cool), and how it hits textures.

NEGATIVE CONSTRAINTS (Standardized):
- tattoos, body markings, text, watermark, illustration, 3d render, cgi, painting, drawing, cartoon, anime, plastic skin, smooth skin, doll-like, fake lighting, studio lighting, flat background, perfect composition, symmetry, oversaturation, distortion, low resolution, extra fingers, bad anatomy, makeup, lipstick.`;

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const prompt = `Analyze this image for a high-end photography recreation.

  Camera Settings to Emulate:
  - Model: ${settings.model}
  - Mode: ${settings.mode}
  - Focal Length: ${settings.focalLength}
  - Lens: ${settings.lensType}
  - Realism Level: ${settings.realism} (If 'Professional Master', allow for artistic shadows and grain).

  INSTRUCTION:
  The user feels previous results looked "flat" and "fake". 
  1. Describe the background with extreme texture and depth. 
  2. Ensure the lighting feels physical and motivated by the scene.
  3. Combine positive and negative prompts into one string.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            { text: prompt },
            {
              inlineData: {
                mimeType: 'image/jpeg',
                data: imageBuffer.split(',')[1],
              },
            },
          ],
        },
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from AI");

    return resultText;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

