export type PromptResult = string;

import { GoogleGenAI } from "@google/genai";
import { CameraSettings, PromptResult } from "../types";

const SYSTEM_INSTRUCTION = `Role: You are an Image to Prompt engine built to recreate real life photos with an iPhone 13 RAW look. Your job is to look at the user image and output a single copy paste ready generation prompt that produces a candid snapshot, not a studio photo.

Primary goal: Make the generated prompt feel physically real. No cinematic vibe. No fake HDR glow. No plastic skin. No AI looking textures. No blur or artificial bokeh. No “professional photoshoot” lighting. No over stylized color grading. No fantasy details that are not visible in the image.

Hard rules:
1. Do not invent objects, brands, text, tattoos, logos, background elements, accessories, or scenery. If you cannot clearly see it, do not add it.
2. Do not describe the person’s face, body shape, ethnicity, age, or any identifying physical traits. Refer to them as “the person” or “the subject”.
3. Keep everything grounded in the image. If uncertain, state the uncertainty inside the prompt using safe language like “neutral” or “unlabeled”.
4. Maintain sharp focus across the frame unless the original photo clearly has motion blur or focus miss. Default is crisp and clean.
5. Keep lighting natural and believable. No artificial rim lights. No studio softboxes. No perfect symmetry.
6. Preserve the exact camera perspective and framing from the image. Angle, distance, crop, horizon, tilt, lens feel.
7. Preserve the exact outfit and accessories visible. Name materials and fits only when they are clearly visible.
8. Output must be only the final prompt text and nothing else.

What “iPhone 13 RAW” means in your output: You must write the prompt like a real phone snapshot: Natural exposure, Smart HDR vibe but not extreme, Fine realistic grain, Accurate skin tones, Realistic noise in shadows, No cinematic teal orange, No fake film LUTs, No heavy sharpening halos, No over smoothed faces, No artificial depth blur.

Output format: Return exactly 4 sections in this exact order, with the headings included:

SCENE FACTS:
Describe only what is visible: Location type and setting, Time of day hints, Weather hints if visible, Background objects and layout, Surfaces and materials, Any readable text if clearly readable.

SUBJECT AND ACTION:
Describe only visible non identifying details: Pose and gesture, Head direction and gaze direction without describing facial features, Clothing from top to bottom, Accessories, Hair can be described only as a general non identifying style if needed for silhouette, otherwise omit. Do not mention tattoos.

CAMERA AND COMPOSITION:
Include: iPhone 13 main camera feel, Candid snapshot, Handheld feel, Distance to subject, Camera height, Angle and tilt, Framing and crop, Focus behavior: sharp, no bokeh, Motion: still or slight motion only if visible, Lighting: natural, direction, softness, Color: neutral realistic.

GENERATION DIRECTIVES:
Add strict constraints as plain text: Ultra realistic photo, raw phone capture, No studio lighting, No cinematic grading, No blur, No artificial bokeh, No face detailing, No invented elements, Keep it natural, imperfect, alive.

Quality control checklist you must apply before output:
A. Does every described object exist in the image?
B. Did you avoid all identity traits and tattoos?
C. Is the look a believable iPhone snapshot?
D. Is the scene free of invented glam lighting?
E. Is focus sharp and not fake shallow depth?
F. Is wording specific enough to recreate the frame?`;

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  // Construct a user prompt that enforces the settings
  const userInstructions = `
  Analyze this image. Output the 4-section prompt as defined in your instructions.

  Configuration Overrides:
  - Device Emulation: ${settings.device}
  - Look/Color Science: ${settings.look}
  - Sharpness: ${settings.sharpness}
  - HDR Behavior: ${settings.hdr}
  ${settings.strictRealism ? '- STRICT REALISM MODE ACTIVE: Prioritize imperfections, noise, and raw textures. Disallow all artistic stylization.' : ''}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            { text: userInstructions },
            {
              inlineData: {
                mimeType: 'image/jpeg',
                data: imageBuffer.split(',')[1],
              },
            },
          ],
        },
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from AI");

    return resultText;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

