              <input 
                type="file" 
                accept="image/*" 
                onChange={handleImageUpload}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20"
              />
              <div className={`
                absolute inset-0 rounded-3xl transition-all duration-500 ease-out overflow-hidden flex flex-col items-center justify-center
                ${image ? 'shadow-xl ring-1 ring-black/5 bg-black' : 'bg-white border-2 border-dashed border-gray-200 hover:border-gray-400 hover:bg-gray-50'}
              `}>
                {image ? (
                  <img src={image} className="w-full h-full object-contain opacity-90" alt="Reference" />
                ) : (
                  <>
                    <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mb-4 group-hover:scale-105 transition-transform duration-300">
