import React, { useState } from 'react';
import { PromptResult } from '../types';

interface Props {
  result: PromptResult | null;
  isLoading: boolean;
}

const PromptDisplay: React.FC<Props> = ({ result, isLoading }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    if (!result) return;
    navigator.clipboard.writeText(result);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (isLoading) {
    return (
      <div className="bg-white rounded-[2rem] border border-gray-100 shadow-sm p-8 h-full min-h-[400px] flex flex-col items-center justify-center space-y-6">
         <div className="w-full max-w-sm space-y-4 animate-pulse">
            <div className="h-2 bg-gray-100 rounded-full w-3/4 mx-auto"></div>
            <div className="h-2 bg-gray-100 rounded-full w-full"></div>
            <div className="h-2 bg-gray-100 rounded-full w-5/6 mx-auto"></div>
         </div>
      </div>
    );
  }

  if (!result) {
