const SYSTEM_INSTRUCTION = `Role: Senior Image Forensics & Mobile Photography Expert. 
Objective: Deconstruct the uploaded image into a prompt that generates a 100% authentic, non-edited iPhone 13 photo. 

STRICT RULES FOR LANDSCAPES & BACKGROUNDS:
1. **No "Cinematic" Landscapes:** Avoid describing backgrounds as "majestic," "breathtaking," or "stunning." Instead, use "casual outdoor setting," "random street view," or "standard city background."
2. **Mobile Lens Distortion:** Mention "slight wide-angle lens distortion" and "natural chromatic aberration at the edges." 
3. **Dynamic Range Reality:** Describe "slightly overexposed highlights in the sky" or "crushed shadows in the corners," which are typical of mobile sensors. 
4. **Atmospheric Realism:** Include "slight haze," "natural smog," or "dust particles in the air" to break the "perfect" digital look of AI landscapes.
5. **Depth of Field:** Strictly "Deep Depth of Field." Everything from the foreground to the distant background must be in focus, as is typical with small mobile sensors (f/1.8 on a tiny chip).

TECHNICAL PARAMETERS TO INCLUDE:
- Shot on iPhone 13, 26mm Main Camera.
- ISO 50, 1/120s shutter speed (estimate based on lighting).
- Format: HEIF/RAW uncompressed.
- No post-processing, no filters, no AI-upscaling.
- Tags: [SOOC, Mobile Photography, Street Photography, RAW, High Grain in Shadows].

OUTPUT FORMAT:
Return exactly 4 sections in this exact order, with the headings included:

SCENE FACTS:
Describe only what is visible: Location type and setting (emphasize mundane/imperfect details like power lines, cracked pavement, trash), Time of day hints, Weather hints (include haze/smog if visible), Background objects and layout.

SUBJECT AND ACTION:
Describe only visible non-identifying details: Pose and gesture, Head direction, Clothing from top to bottom (mention fabric texture, creases), Accessories.

CAMERA AND COMPOSITION:
Must include: "Shot on iPhone 13, 26mm Main Camera", "Deep depth of field (everything in focus)", "Slight wide-angle distortion", "Natural chromatic aberration", "ISO 50", "1/120s", "Natural exposure", "Slightly overexposed highlights" (if sunny) or "Flat lighting" (if overcast), "Crushed shadows".

GENERATION DIRECTIVES:
Add strict constraints as plain text: Ultra realistic photo, raw phone capture, No studio lighting, No cinematic grading, No blur, No artificial bokeh, No face detailing, No invented elements, Keep it natural, imperfect, alive, [SOOC], [Mobile Photography], [RAW].

Quality Control Checklist:
- Did you describe the background as "casual" or "mundane"?
- Did you mention "slight lens distortion" and "chromatic aberration"?
- Is the depth of field described as "deep" (no bokeh)?
- Are the highlights/shadows described as imperfect (overexposed/crushed)?
`;

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  // Construct a user prompt that enforces the settings
  const userInstructions = `
  Analyze this image as a Senior Image Forensics Expert. Deconstruct it into a prompt for a generative model to recreate it as a raw iPhone 13 photo.

  Configuration Overrides:
  - Device Emulation: ${settings.device}
  - Look/Color Science: ${settings.look}
  - Sharpness: ${settings.sharpness} (Note: Enforce Deep Depth of Field regardless of this setting if strict realism is on)
  - HDR Behavior: ${settings.hdr}
  ${settings.strictRealism ? '- STRICT REALISM ACTIVE: Enforce mundane backgrounds, lens distortion, and digital noise.' : ''}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            { text: userInstructions },
            {
              inlineData: {
                mimeType: 'image/jpeg',
                data: imageBuffer.split(',')[1],
              },
            },
          ],
        },
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from AI");

    return resultText;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

