import { GoogleGenAI } from "@google/genai";
import { CameraSettings, PromptResult } from "../types";

const SYSTEM_INSTRUCTION = `Role: You are a Concise Visual Fact-Checker.

Your goal is to fill the template below using ONLY confirmed visual facts.
The user wants a SHORT, realistic prompt. DO NOT Write long poetic descriptions.

CRITICAL RULES:
1. **NO HALLUCINATIONS:** Do NOT describe reflections in sunglasses/eyes. Do NOT describe people that are not clearly visible. Do NOT invent logos if they aren't readable.
2. **BE CONCISE:** Describe clothing and background in 5-10 words maximum per section.
3. **PRESERVE TEMPLATE:** Do not change the fixed text.

MANDATORY TEMPLATE:
Subject : [blank]
The most real and human possible, create an image that looks like a portrait taken by someone else using an iPhone back camera, capturing a casual, unintentional moment [SCENE_CONTEXT]. The subject is wearing the same outfit and accessories as in the reference photo: [CONCISE_CLOTHING]; nothing is altered or stylized. The subject [SIMPLE_ACTION]. [CONCISE_BACKGROUND]. There should be no clear subject or specific composition — just a spontaneous snapshot with off-center, slightly crooked framing, part of the face sharply captured, and a hint of natural hand motion blur from the quick capture. No color grading, no stylization, no cinematic look; the tone is neutral, not too cool, not too warm. The background must be fully sharp and in focus — no bokeh, no depth-of-field effect, no portrait mode. The camera orientation is portrait with a 3:4 aspect ratio. It must not look AI-generated, but rather like it was taken by a real person. [DO NOT CHANGE SUBJECT/S’ FACIAL FEATURES]

INSTRUCTIONS FOR FILLING BRACKETS:
- [SCENE_CONTEXT]: 2-3 words only (e.g., "at a park", "in a kitchen").
- [CONCISE_CLOTHING]: List items simply (e.g., "a black t-shirt and blue jeans"). No fancy adjectives.
- [SIMPLE_ACTION]: What are they doing? (e.g., "looking at phone", "standing still").
- [CONCISE_BACKGROUND]: Name the location/objects behind simply (e.g., "a white wall and a wooden door").
`;

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const userInstructions = `
  Analyze this image. Fill the MANDATORY TEMPLATE.

  STRICT CONSTRAINTS:
  - Subject Description: ONLY describe the clothes and simple pose.
  - NO REFLECTIONS: Do not mention what is reflected in glasses.
  - NO EXAGGERATION: Keep it boring and realistic.
  - KEEP IT SHORT.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            { text: userInstructions },
            {
              inlineData: {
                mimeType: 'image/jpeg',
                data: imageBuffer.split(',')[1],
              },
            },
          ],
        },
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.1, // Lowest temperature for maximum factuality and minimum creativity
      },
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from AI");

    return resultText;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

