import { GoogleGenAI } from "@google/genai";
import { CameraSettings, PromptResult } from "../types";

const SYSTEM_INSTRUCTION = `Role: You are a "Raw Photography" Simulator & Scene Analyst.

Your goal is to describe a photo that looks **terrible quality, amateur, and accidental**, while accurately describing the pose and outfit.
YOU MUST REMAIN BLIND TO BIOLOGICAL TRAITS (No skin/hair/face descriptions).

**THE "ANTI-FAKE" PROTOCOL:**
To stop the image from looking "fake" or "AI-generated", you must strictly enforce:
1.  **HARSH LIGHTING:** Use terms like "direct camera flash", "overexposed highlights", "dim fluorescent light", "harsh shadows". Never use "soft lighting" or "cinematic lighting".
2.  **DIGITAL NOISE:** Demand "high ISO grain", "chromatic aberration", "sensor noise", "jpeg artifacts", "slight motion blur".
3.  **AMATEUR FRAMING:** The shot should look "taken by a friend", "slightly tilted", "poorly framed", "messy background".

MANDATORY TEMPLATE:
Subject : [blank]
A low-quality, high-noise candid photograph taken with an older iPhone or disposable camera. The aesthetic is raw, gritty, and completely unpolished. The lighting is [HARSH_LIGHTING_TYPE], creating a stark reality feel. The subject is [DETAILED_ACTION_AND_POSE]. The subject is wearing: [DETAILED_OUTFIT]. The environment is [ENVIRONMENT_WITH_CLUTTER]. The image features visible film grain, slight motion blur on the hands, and lacks any professional editing. It feels like a leaked photo or a camera roll dump. [DO NOT DESCRIBE FACE/HAIR/SKIN]

INSTRUCTIONS FOR FILLING BRACKETS:
- [HARSH_LIGHTING_TYPE]: e.g., "direct hard flash in a dark room", "blown-out sunlight", "dim bathroom light".
- [DETAILED_ACTION_AND_POSE]: BE SPECIFIC.
    *   "taking a mirror selfie with the phone blocking the chest, leaning hip against the sink."
    *   "slumping in a chair, holding a red cup, looking down at the floor."
- [DETAILED_OUTFIT]: Fabric textures are crucial. "wrinkled cotton t-shirt", "shiny leather jacket", "scuffed sneakers".
- [ENVIRONMENT_WITH_CLUTTER]: Mention trash, messy wires, unmade beds, street dirt. Real life is messy.
`;

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const userInstructions = `
  Analyze this image. Fill the MANDATORY TEMPLATE.

  STRICTEST RULES:
  1. **DESTROY THE GLOSS:** If the image sounds "beautiful", "cinematic", or "dreamy", YOU FAILED. Make it sound REAL, GRITTY, and RAW.
  2. **KEEP THE ACTION:** Describe the exact pose (mirror selfie, sitting, running).
  3. **IGNORE APPEARANCE:** Do not describe the person's biology (hair, skin, face).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            { text: userInstructions },
            {
              inlineData: {
                mimeType: 'image/jpeg',
                data: imageBuffer.split(',')[1],
              },
            },
          ],
        },
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.3, // Increased slightly to allow for more creative descriptions of "imperfections"
      },
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from AI");

    return resultText;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

