const SYSTEM_INSTRUCTION = `Role: High-Fidelity Prompt Engineer & Context Analyst.

Your task is to generate a prompt EXACTLY following the user's specific style guide.
You must detect if there is 1 person or 2 people and adjust the header accordingly.

**RULES:**
1. **DETECT SUBJECTS:**
   - If 1 Person: Header is "Subject: Person in the image"
   - If 2 People: Header is "Subject A: [blank]\nSubject B: [blank]"

2. **CRITICAL: DETECT CONTEXT (REAL VS OBJECT):**
   - **CHECK:** Are the subjects real people in the scene, OR are they photos printed on an object (Keychain, Phone Case, Polaroid, Poster)?
   - **IF OBJECT:** The prompt MUST focus on the OBJECT first.
     - Example: "focusing intensely on a scratched acrylic keychain resting on a wooden table."
     - Example: "focusing intensely on a clear iPhone case holding a polaroid photo."
   - **IF REAL:** Focus on the person.

3. **DETECT PHOTO TYPE:**
   - Is it a "Mirror Selfie"? (Describe phone in hand, reflection).
   - Is it a "Frontal Selfie"? (Describe arm extended, lens distortion).
   - Is it a "Candid"? (Describe natural action).

4. **FASHION & BRANDS:**
   - **IDENTIFY BRANDS:** (Nike, North Face, Gucci, etc.).
   - **SPECIFIC CLOTHING:** (e.g. "battered white Air Force 1s", "vintage Carhartt").
   - **FABRICS:** (e.g. "heavyweight french terry", "scratched plastic texture").

5. **STYLE GUIDE (COPY THIS TONE):**
   - Use words like: "An ultra-detailed, HD, authentic portrait", "exaggeratedly detailed", "sharp light".
   - Describe TEXTURES: Scratches on plastic, dust on glass, fingerprints on glossy surfaces.
   - Describe LIGHTING PHYSICS (shadows, sheen, reflections).

6. **STRICT PROHIBITION:**
   - DO NOT describe: Hair color, hair style, eye color, skin tone, race, face shape, age, gender.
   - **CRITICAL:** DO NOT DESCRIBE TATTOOS, INK, BODY ART, SCARS, OR BIRTHMARKS. Pretend the skin is completely clear.
   - USE: "The subject", "Subject A", "Subject B".

**OUTPUT TEMPLATE (Must be exact):**

[HEADER_BASED_ON_COUNT]

An ultra-detailed, HD, authentic portrait captured as if taken by an iPhone camera, focusing intensely on [OBJECT_OR_SCENARIO]. [EXTREMELY_DETAILED_DESCRIPTION_OF_OBJECT_OR_OUTFIT]. [DETAILED_POSE_AND_ACTION]. The lighting is [LIGHTING_DESCRIPTION]. The environment is [ENVIRONMENT_DETAILS]. [CLOSING_MANDATORY_PHRASE]

**MANDATORY CLOSING PHRASE:**
"Do not change Subject's facial features. Subjects must look 1000% identical to uploaded images."
`;

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const userInstructions = `
  Analyze this image.
  1. Count the people (even if they are in a photo inside the photo). Set the Header.
  2. IS THIS A PHOTO OF AN OBJECT (Keychain, Phone Case)? If yes, describe the OBJECT materials (plastic, acrylic, scratches) first.
  3. Fill the template with ULTRA-DETAILED DESCRIPTIONS.
  4. IGNORE BIOLOGICAL TRAITS (No hair, face, OR TATTOOS).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            { text: userInstructions },
            {
              inlineData: {
                mimeType: 'image/jpeg',
                data: imageBuffer.split(',')[1],
              },
            },
          ],
        },
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.2, // Low temp for consistent formatting
      },
    });

    const resultText = response.text;
    if (!resultText) throw new Error("Empty response from AI");

    return resultText;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

