const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const userInstructions = `
  Analyze this image.
  1. IS IT AN OBJECT (Keychain/Case)? If yes, describe the PLASTIC/ACRYLIC texture, reflections, and dust.
  2. Describe the CLOTHING/BRANDS in extreme detail.
  3. STYLE: RAW, UNFILTERED, FLAT COLORS. NO SATURATION.
  4. IGNORE BIOLOGICAL TRAITS (No hair, face, OR TATTOOS).
  5. OUTPUT FORMAT: Just the prompt. No intro. No Headers.
  `;

  let lastError: any = null;
  const maxRetries = 3;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          {
            parts: [
              { text: userInstructions },
              {
                inlineData: {
                  mimeType: 'image/jpeg',
                  data: imageBuffer.split(',')[1],
                },
              },
            ],
          },
        ],
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          temperature: 0.3, 
        },
      });

      const resultText = response.text;
      if (!resultText) throw new Error("Empty response from AI");

      return resultText;
    } catch (error: any) {
      lastError = error;
      // Check for rate limit (429) or service unavailable (503)
      const isRetryable = error.status === 429 || error.code === 429 || error.message?.includes('429') || 
                          error.status === 503 || error.code === 503;

      if (isRetryable && attempt < maxRetries - 1) {
        const delay = 1000 * Math.pow(2, attempt); // Exponential backoff: 1s, 2s, 4s
        console.warn(`Gemini API busy (429/503), retrying in ${delay}ms... (Attempt ${attempt + 1}/${maxRetries})`);
        await wait(delay);
        continue;
      }

      // If not retryable or last attempt, break loop
      break;
    }
  }

  console.error("Gemini Error:", lastError);

  // Provide a user-friendly error message for quotas
  if (lastError?.status === 429 || lastError?.code === 429 || lastError?.message?.includes('429')) {
    throw new Error("High traffic volume (Quota Exceeded). Please wait a few seconds and try again.");
  }

  throw lastError;
};

