// Helper for image compression
const compressImage = (base64Str: string): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.src = base64Str;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const MAX_WIDTH = 1024;
      const MAX_HEIGHT = 1024;
      let width = img.width;
      let height = img.height;

      if (width > height) {
        if (width > MAX_WIDTH) {
          height *= MAX_WIDTH / width;
          width = MAX_WIDTH;
        }
      } else {
        if (height > MAX_HEIGHT) {
          width *= MAX_HEIGHT / height;
          height = MAX_HEIGHT;
        }
      }
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(img, 0, 0, width, height);
      resolve(canvas.toDataURL('image/jpeg', 0.8));
    };
  });
};

const App: React.FC = () => {
  const settings: CameraSettings = {
    device: 'iPhone 13',
    look: 'RAW',
    sharpness: 'Natural',
    hdr: 'Natural',
    strictRealism: true
  };

  const [image, setImage] = useState<string | null>(null);
  const [compressedImage, setCompressedImage] = useState<string | null>(null);
  const [result, setResult] = useState<PromptResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const lastProcessedImage = useRef<string | null>(null);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setImage(base64);
        setError(null);
        setResult(null);
        const compressed = await compressImage(base64);
        setCompressedImage(compressed);
      };
      reader.readAsDataURL(file);
    }
  };

  const generate = useCallback(async (imgToProcess: string) => {
    if (isLoading || imgToProcess === lastProcessedImage.current) return;

    setIsLoading(true);
    setError(null);
    lastProcessedImage.current = imgToProcess;

    try {
      const data = await generatePrompts(imgToProcess, settings);
      setResult(data);
    } catch (err: any) {
      setError(err.message);
      lastProcessedImage.current = null; // Allow retry
    } finally {
      setIsLoading(false);
    }
