import { CameraSettings, PromptResult } from "../types";

const SYSTEM_INSTRUCTION = `You are a professional image-to-prompt engine. Your goal is to reverse-engineer photos into high-detail prompts for AI generators.

STRICT OUTPUT FORMAT:
The response must be exactly one single, continuous paragraph. 
It MUST start exactly with: "Subject: Person in the image "
It MUST end exactly with: " Do not change Subject's facial features. Subjects must look 1000% identical to uploaded images."

CONTENT REQUIREMENTS:
- Describe the scene as a RAW, unedited iPhone photo.
- Include extreme detail about textures (fabric mesh, skin pores, reflections).
- Describe the lighting (ambient vs screen glow, shadows).
- Describe background elements (objects, clutter, software windows).
- Use technical camera language (HD, 8k, authentic portrait, iPhone camera).
- Avoid bullet points, headers, or any conversational text.
`;

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key configuration missing.");

  const ai = new GoogleGenAI({ apiKey });

  const userInstructions = `
    Analyze this image. 
    Format: Single paragraph starting with "Subject: Person in the image ".
    Details to include: ${settings.device} style, ${settings.look} color profile, ultra-detailed textures.
  `;

  let lastError: any = null;
  const maxRetries = 5; // Increased retries

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      // Using gemini-3-flash-preview as it supports multimodal and is robust
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview', 
        contents: [
          {
            parts: [
              { text: userInstructions },
              {
                inlineData: {
                  mimeType: 'image/jpeg',
                  data: imageBuffer.split(',')[1],
                },
              },
            ],
          },
        ],
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          temperature: 0.4,
        },
      });

      const resultText = response.text;
      if (!resultText) throw new Error("API returned an empty response.");

      return resultText.trim();
    } catch (error: any) {
      lastError = error;

      // Extract deep error message
      const errorMessage = error.message || 
                          error.statusText || 
                          (error.error ? error.error.message : '') || 
                          JSON.stringify(error);

      console.warn(`Attempt ${attempt + 1} failed: ${errorMessage}`);

      // Retry logic for rate limits (429) or server issues (503)
      const isRetryable = errorMessage.includes('429') || 
                         errorMessage.includes('503') || 
                         errorMessage.includes('quota') || 
                         errorMessage.includes('Overloaded');

      if (isRetryable && attempt < maxRetries - 1) {
        // Exponential backoff: 2s, 4s, 8s, 16s, 32s
        const delay = 2000 * Math.pow(2, attempt) + (Math.random() * 500);
        await wait(delay);
        continue;
      }

      // If not retryable, throw immediately
      break;
    }
  }

  // Final error handling
  const finalMsg = lastError?.message || JSON.stringify(lastError);

  if (finalMsg.includes('429') || finalMsg.includes('quota')) {
    throw new Error("System is at capacity (Rate Limit). Please wait 30 seconds and try again.");
  }

  if (finalMsg.includes('SAFETY')) {
    throw new Error("The image was flagged by safety filters. Please try a different photo.");
  }

  throw new Error(`Generation failed: ${finalMsg.substring(0, 100)}...`);
};

