import { GoogleGenAI } from "@google/genai";
import { CameraSettings, PromptResult } from "../types";

const SYSTEM_INSTRUCTION = `Role: Hyper-Realistic Forensic Image Describer.

Your goal is to generate a prompt that results in a 100% authentic, unedited, "accidentally taken" iPhone photo.
You must strip away all "beauty", "art", and "cinema". You must focus on "reality", "grit", "dust", and "imperfection".

**STRICT TEMPLATE (FOLLOW THIS STRUCTURE):**
"Subject: Person in the image

An ultra-detailed, HD, authentic portrait captured as if taken by an iPhone camera, focusing intensely on the [Subject] in the image [context/action]. [He/She] is wearing [extremely detailed outfit description: mention heavy fabrics, exaggerated weaves, dust particles on clothes, tightness of knots, pooling of trousers]. The [Subject] is positioned [precise posture: straight-backed, leaning, hands clasped/interwoven]. The lighting is [realistic source: strong artificial, overhead stage lights, harsh office flourescent], casting crisp, defined shadows and creating a slight sheen on [glasses/skin/objects]. The environment is [cluttered/formal/messy]; [describe blurred background figures or objects to emphasize depth]. The floor/surface is [specific texture: mottled, dark, speckled with tiny imperfections and reflections], grounding the whole scene in gritty, natural realism. Do not change Subject's facial features. Subjects must look 1000% identical to uploaded images."

**MANDATORY DETAILS TO INCLUDE:**
1. **Texture:** "fabric weave that catches fine dust particles", "mottled surfaces", "fingerprints on glasses".
2. **Imperfections:** "tiny imperfections", "speckled floor", "scuffs", "wrinkles".
3. **Lighting:** "sharp light", "defined shadows", "strong artificial light" (AVOID "soft", "glow", "golden hour").
4. **Camera:** "iPhone camera", "natural mobile-camera noise", "slight blur on background".

**BANNED WORDS (DO NOT USE):**
- Cinematic, Masterpiece, Trending on ArtStation, 8k, Unreal Engine, Octane Render.
- Dramatic lighting, Volumetric lighting, God rays.
- Vibrant, Pop, Stylized.

**OUTPUT FORMAT:**
- EXACTLY two parts separated by a double line break.
- Part 1: "Subject: Person in the image"
- Part 2: The long, dense, gritty paragraph described above.
`;

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generatePrompts = async (
  imageBuffer: string, 
  settings: CameraSettings
): Promise<PromptResult> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key configuration missing.");

  const ai = new GoogleGenAI({ apiKey });

  const userInstructions = `
    Analyze this image and generate a PROMPT following the STRICT TEMPLATE.

    CRITICAL FOCUS:
    - CLOTHING: Fabric weight, weave, dust particles, wrinkles.
    - LIGHTING: Harsh, artificial, sharp shadows. NO HDR. NO FILTERS.
    - ENVIRONMENT: Mottled floors, clutter, imperfections.
    - POSE: Exact forensic description of hands, spine, head tilt.
  `;

  let lastError: any = null;
  const maxRetries = 3; 

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview', 
        contents: [
          {
            parts: [
              { text: userInstructions },
              {
                inlineData: {
                  mimeType: 'image/jpeg',
                  data: imageBuffer.split(',')[1],
                },
              },
            ],
          },
        ],
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          temperature: 0.1, // Very low temperature for maximum adherence to the template
        },
      });

      const resultText = response.text;
      if (!resultText) throw new Error("API returned an empty response.");

      return resultText.trim();
    } catch (error: any) {
      lastError = error;

      const errorMessage = error.message || JSON.stringify(error);
      console.warn(`Attempt ${attempt + 1} failed: ${errorMessage}`);

      const isRetryable = errorMessage.includes('429') || errorMessage.includes('503');

      if (isRetryable && attempt < maxRetries - 1) {
        const delay = 2000 * Math.pow(2, attempt);
        await wait(delay);
        continue;
      }
      break;
    }
  }

  const finalMsg = lastError?.message || JSON.stringify(lastError);
  if (finalMsg.includes('429')) {
    throw new Error("High traffic. Please wait 10 seconds and retry.");
  }
  throw new Error(`Analysis failed: ${finalMsg.substring(0, 80)}...`);
};

