  const finalMsg = lastError?.message || JSON.stringify(lastError);
  if (finalMsg.includes('429')) {
    throw new Error("High traffic. Please wait 10 seconds and retry.");
  }
  throw new Error(`Analysis failed: ${finalMsg.substring(0, 80)}...`);
};
